function drawChart(svg, data, axisMax, opts) {
  const ns = 'http://www.w3.org/2000/svg';
  const plot = opts.plot; // {left, top, width, height}
  const ticks = opts.ticks; // array of tick values
  const orientation = opts.orientation || 'vertical';
  const barWidth = opts.barWidth || 60;
  const barGap = opts.barGap || 20;
  const xLabels = opts.xLabels || [];
  const yTitle = opts.yTitle || '';
  const xTitle = opts.xTitle || '';
  const valueLabels = opts.valueLabels || true;
  const labelOffset = opts.labelOffset || 6;
  const labelColor = opts.labelColor || '#111';
  const barColor = opts.barColor || '#4a90e2';
  const gridColor = opts.gridColor || '#ccc';
  const axisColor = opts.axisColor || '#999';

  // clear existing? We'll build from scratch, but SVG already has axes? We'll remove existing children? Better to create all inside a group. But we need to not duplicate. We can remove all children of svg first.
  while (svg.firstChild) svg.removeChild(svg.firstChild);

  // function to add element
  function el(tag, attrs) {
    const e = document.createElementNS(ns, tag);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    svg.appendChild(e);
    return e;
  }

  // draw axes
  if (orientation === 'vertical') {
    // y-axis line
    el('line', {x1: plot.left, y1: plot.top, x2: plot.left, y2: plot.top+plot.height, stroke: axisColor, 'stroke-width': 1});
    // x-axis line
    el('line', {x1: plot.left, y1: plot.top+plot.height, x2: plot.left+plot.width, y2: plot.top+plot.height, stroke: axisColor, 'stroke-width': 1});
    // gridlines and y labels
    ticks.forEach(v => {
      const y = plot.top + plot.height - (v/axisMax)*plot.height;
      el('line', {x1: plot.left, y1: y, x2: plot.left+plot.width, y2: y, stroke: gridColor, 'stroke-width': 1});
      el('text', {x: plot.left-6, y: y+4, 'font-size': 18, fill: '#333', 'text-anchor': 'end'}, v);
    });
    // x labels
    xLabels.forEach((label, i) => {
      const cx = plot.left + plot.width * (i+0.5) / xLabels.length;
      el('text', {x: cx, y: plot.top+plot.height+30, 'font-size': 18, fill: '#333', 'text-anchor': 'middle'}, label);
    });
    // bars
    const n = data.length;
    const slot = plot.width / n;
    const bw = Math.min(barWidth, slot - barGap);
    data.forEach((d, i) => {
      const cx = plot.left + slot * (i+0.5);
      const x = cx - bw/2;
      const h = (d.value/axisMax)*plot.height;
      const y = plot.top + plot.height - h;
      el('rect', {x, y, width: bw, height: h, fill: d.color || barColor});
      if (valueLabels) {
        el('text', {x: cx, y: y-6, 'font-size': 18, fill: labelColor, 'text-anchor': 'middle'}, d.value);
      }
    });
    // axis titles
    if (yTitle) {
      const ty = plot.top + plot.height/2;
      const t = el('text', {x: 20, y: ty, 'font-size': 18, fill: '#333', transform: `rotate(-90 20 ${ty})`, 'text-anchor': 'middle'}, yTitle);
    }
    if (xTitle) {
      el('text', {x: plot.left+plot.width/2, y: plot.top+plot.height+60, 'font-size': 18, fill: '#333', 'text-anchor': 'middle'}, xTitle);
    }
  } else {
    // horizontal
    // x-axis line
    el('line', {x1: plot.left, y1: plot.top, x2: plot.left+plot.width, y2: plot.top, stroke: axisColor, 'stroke-width': 1});
    // y-axis line
    el('line', {x1: plot.left, y1: plot.top, x2: plot.left, y2: plot.top+plot.height, stroke: axisColor, 'stroke-width': 1});
    // gridlines and x labels
    ticks.forEach(v => {
      const x = plot.left + (v/axisMax)*plot.width;
      el('line', {x1: x, y1: plot.top, x2: x, y2: plot.top+plot.height, stroke: gridColor, 'stroke-width': 1});
      el('text', {x: x, y: plot.top+plot.height+20, 'font-size': 18, fill: '#333', 'text-anchor': 'middle'}, v);
    });
    // bars
    const n = data.length;
    const slot = plot.height / n;
    const bh = Math.min(barWidth, slot - barGap);
    data.forEach((d, i) => {
      const cy = plot.top + slot * (i+0.5);
      const y = cy - bh/2;
      const w = (d.value/axisMax)*plot.width;
      const x = plot.left;
      el('rect', {x, y, width: w, height: bh, fill: d.color || barColor});
      if (valueLabels) {
        el('text', {x: x+w+10, y: cy+6, 'font-size': 20, fill: labelColor, 'text-anchor': 'start'}, d.label);
      }
    });
    // category labels on left
    data.forEach((d, i) => {
      const cy = plot.top + slot * (i+0.5);
      el('text', {x: plot.left-10, y: cy+6, 'font-size': 20, fill: '#111', 'text-anchor': 'end'}, d.category);
    });
    // axis titles
    if (xTitle) {
      el('text', {x: plot.left+plot.width/2, y: plot.top+plot.height+50, 'font-size': 18, fill: '#333', 'text-anchor': 'middle'}, xTitle);
    }
    if (yTitle) {
      const tx = plot.left - 40;
      const ty = plot.top + plot.height/2;
      el('text', {x: tx, y: ty, 'font-size': 18, fill: '#333', transform: `rotate(-90 ${tx} ${ty})`, 'text-anchor': 'middle'}, yTitle);
    }
  }
}

